                'U.S. with laws that may be interpreted to impose limitations on this direct-to-consumer sales model. '
                'It has also been asserted that the laws in some states limit our ability to obtain dealer licenses '
                'from state motor vehicle regulators, and such assertions persist. In certain locations, decisions by '
                'regulators permitting us to sell vehicles have been, and may be, challenged by dealer associations '
                'and others as to whether such decisions comply with applicable state motor vehicle industry laws. We '
                'have prevailed in many of these lawsuits and such results have reinforced our continuing belief that '
                'state franchise laws were not intended to apply to a manufacturer that does not have franchise '
                'dealers anywhere in the world. In some states, there have also been regulatory and legislative '
                'efforts by dealer associations to propose laws that, if enacted, would prevent us from obtaining '
