                'put pressure on the supply and demand for our common stock, further influencing volatility in its '
                'market price. Public perception of our company or management and other factors outside of our control '
                'may additionally impact the stock price of companies like us that garner a disproportionate degree of '
                'public attention, regardless of actual operating performance. In addition, in the past, following '
