    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 40)',
        'text': 'Automotive & Services and Other Segment\n'
                '\n'
                'Automotive sales revenue includes revenues related to cash and financing deliveries of new vehicles, '
                'including access to our FSD (Supervised) features and their ongoing maintenance, internet '
                'connectivity, free Supercharging programs and over-the-air software updates. These deliveries are '
                'vehicles that are not subject to lease accounting.\n'
                '\n'
                'Automotive regulatory credits includes sales of regulatory credits to other automotive manufacturers. '
                'Our revenue from automotive regulatory credits is directly related to our new vehicle production, '
                'sales and pricing negotiated with our customers. We monetize them proactively as new vehicles are '
                'sold based on standing arrangements with buyers of such credits, typically as close as possible to '
                'the production and delivery of the vehicle or changes in regulation impacting the credits.\n'
                '\n'
                'Automotive leasing revenue includes the amortization of revenue for vehicles under direct operating '
                'lease agreements. Additionally, automotive leasing revenue includes direct sales-type leasing '
                'programs where we recognize all revenue associated with the sales-type lease upon delivery to the '
                'customer.\n'
                '\n'
                'Services and other revenue consists of sales of used vehicles, non-warranty maintenance services and '
                'collision, part sales, paid Supercharging, insurance services revenue and retail merchandise sales.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 40)',
        'text': '2024 compared to 202\n'
                '\n'
                'Automotive sales revenue decreased $6.03 billion, or 8%, in the year ended December 31, 2024 as '
                'compared to the year ended December 31, 2023, primarily due to lower average selling price on our '
                'vehicles driven by overall price reductions and attractive financing options provided in 2024 as well '
                'as mix. Additionally, there was a decrease of approximately 22,000 combined Model 3 and Model Y cash '
                'deliveries. The decreases were partially offset by an increase of approximately 19,000 deliveries of '
                'other models primarily due to our production ramp of Cybertruck. Additionally, we recognized $596 '
                'million of FSD (Supervised) revenue due to release of certain features in 2024.\n'
                '\n'
                '37\n'
                '\n'
                '1%\n'
                '\n'
                'Automotive regulatory credits revenue increased $973 million, or 54%, in the year ended December 31, '
                '2024 as compared to the year ended December 31, 2023, driven by demand for credits in North America '
                'as other automobile manufacturers scale back on their battery electric vehicle plans.\n'
                '\n'
                'Automotive leasing revenue decreased $293 million, or 14%, in the year ended December 31, 2024 as '
                'compared to the year ended December 31, 2023, primarily due to lower direct sales-type leasing '
                'deliveries as we have shifted towards providing leasing options through commercial banking partner '
                'programs that allow for us to recognize upfront revenue in automotive sales and a decrease in lease '
                'buyouts.\n'
                '\n'
                'Services and other revenue increased $2.22 billion, or 27%, in the year ended December 31, 2024 as '
                'compared to the year ended December 31, 2023, primarily due to increases in sales of used vehicles, '
                'non-warranty maintenance services and collision revenue, paid Supercharging revenue, insurance '
                'services revenue and part sales revenue.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 41)',
        'text': 'Energy Generation and Storage Segment\n'
                '\n'
                'Energy generation and storage revenue includes sales and leasing of solar energy generation and '
                'energy storage products, financing of solar generation products, services related to such products '
                'and sales of solar energy systems incentives.\n'
                '\n'
                '2024 compared to 2023\n'
                '\n'
                'Energy generation and storage revenue increased $4.05 billion, or 67%, in the year ended December 31, '
                '2024 as compared to the year ended December 31, 2023, primarily due to a 16.7 GWh increase in '
                'Megapack and Powerwall deployments compared to the prior year.'},
