                '\n'
                'Cost of energy generation and storage revenue increased $2.55 billion, or 52%, in the year ended '
                'December 31, 2024 as compared to the year ended December 31, 2023, primarily due to increases in '
                'Megapack and Powerwall deployments, partially offset by increases in IRA manufacturing credits '
                'recognized as compared to the prior year.\n'
                '\n'
