                '\n'
                'Cash Flows from Operating Activities\n'
                '\n'
                'Our cash flows from operating activities are significantly affected by our cash investments to '
                'support the growth of our business in areas such as research and development and selling, general and '
                'administrative and working capital. Our operating cash inflows include cash from vehicle sales and '
                'related servicing, customer lease and financing payments, customer deposits, cash from sales of '
                'regulatory credits and energy generation and storage products, and interest income on our cash and '
                'investments portfolio. These cash inflows are offset by our payments to suppliers for production '
                'materials and parts used in our manufacturing process, operating expenses, operating lease payments '
                'and interest payments on our financings.\n'
