    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 57)',
        'text': 'Note 1 - Overview\n'
                '\n'
                'Tesla, Inc. (“Tesla”, the “Company”, “we”, “us” or “our”) was incorporated in the State of Delaware '
                'on July 1, 2003 and converted to a Texas corporation on June 13, 2024. We design, develop, '
                'manufacture, sell and lease high-performance fully electric vehicles and energy generation and '
                'storage systems, and offer services related to our products.\n'
                '\n'
                'Note 2 - Summary of Significant Accounting Policies\n'
                '\n'
                'Principles of Consolidation\n'
                '\n'
                'The accompanying consolidated financial statements have been prepared in conformity with GAAP and '
                'reflect our accounts and operations and those of our subsidiaries in which we have a controlling '
                'financial interest. In accordance with the provisions of ASC 810, Consolidation (“ASC 810”), we '
                'consolidate any variable interest entity (“VIE”) of which we are the primary beneficiary. We have '
                'formed VIEs with financing fund investors in the ordinary course of business in order to facilitate '
                'the funding and monetization of certain attributes associated with solar energy systems and leases '
                'under our direct vehicle leasing programs. The typical condition for a controlling financial interest '
                'ownership is holding a majority of the voting interests of an entity; however, a controlling '
                'financial interest may also exist in entities, such as VIEs, through arrangements that do not involve '
                'controlling voting interests. 810 requires a variable interest holder to consolidate a VIE if that '
                'party has the power to direct the activities of the VIE that most significantly impact the VIE’s '
                'economic performance and the obligation to absorb losses of the VIE that could potentially be '
                'significant to the VIE or the right to receive benefits from the VIE that could potentially be '
                'significant to the VIE. We do not consolidate a VIE in which we have a majority ownership interest '
                'when we are not considered the primary beneficiary. We have determined that we are the primary '
                'beneficiary of all the VIEs (see Note 15, Variable Interest Entity Arrangements). We evaluate our '
                'relationships with all the VIEs on an ongoing basis to ensure that we continue to be the primary '
                'beneficiary. All intercompany transactions and balances have been eliminated upon consolidation.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 57)',
        'text': 'Use of Estimates\n'
                '\n'
                'The preparation of financial statements in conformity with GAAP requires management to make estimates '
                'and assumptions that affect the reported amounts of assets, liabilities, revenues, costs and expenses '
                'and related disclosures in the accompanying notes. The estimates used for, but not limited to, '
                'determining significant economic incentive for resale value guarantee arrangements, sales return '
                'reserves, resale value guarantee liabilities, income taxes, the collectability of accounts and '
                'finance receivables, inventory valuation, warranties, fair value of long-lived assets, goodwill, fair '
                'value of financial instruments, fair value and residual value of operating lease vehicles and solar '
                'energy systems subject to leases could be impacted. We have assessed the impact and are not aware of '
                'any specific events or circumstances that required an update to our estimates and assumptions or '
                'materially affected the carrying value of our assets or liabilities as of the date of issuance of '
                'this Annual Report on Form 10-K. These estimates may change as new events occur and additional '
                'information is obtained. Actual results could differ materially from these estimates under different '
                'assumptions or conditions.'},
