                '206.02 Cancelled (3,996) $ 205.61 (4,957) $ 221.15 End of period 344,535 ¢ 40.41 3.51 $ 125.22 18,661 '
                '¢ 233.02 ——— —< Vested and expected to vest, December 31, 2024 344,215 $ 40.23 3.50 $ 125.16 18,409 $ '
                '232.99 Exercisable and vested, December 31, 2024 323,847 $ 27.75, 3.14 $ 121.79\n'
                '\n'
                'The weighted-average grant date fair value per share of RSUs granted in the years ended December 31, '
                '2024, 2023 and 2022 was $223.98, $228.33 and $239.85, respectively. The aggregate release date fair '
                'value of RSUs in the years ended December 31, 2024, 2023 and 2022 was $1.75 billion, $2.50 billion '
