                'earnings we intend to repatriate in the future. For the earnings we intend to indefinitely reinvest, '
                'deferred tax liabilities for foreign withholding or other taxes have been recorded. The estimated '
                'amount of such unrecognized withholding tax liability associated with the indefinitely reinvested '
                'earnings is approximately $309 million.\n'
