                'from) income taxes line of our consolidated statements of operations of $23 million, $17 million and '
                '$27 million for the years ended December 31, 2024, 2023 and 2022, respectively. As of December 31, '
                '2024, and 2023, we have accrued $69 million $47 million, respectively, related to interest and '
                'penalties on our unrecognized tax benefits. Unrecognized tax benefits of $1.14 billion, if '
                'recognized, would affect our effective tax rate.\n'
                '\n'
                'We file income tax returns in the U.S. and various state and foreign jurisdictions. We are currently '
                'under examination by the Internal Revenue Service (“IRS”) for the years 2015 to 2018. Additional tax '
                'years within the periods 2004 to 2014 and 2019 to 2023 remain subject to examination for federal '
                'income tax purposes. All net operating losses and tax credits generated to date are subject to '
                'adjustment for U.S. federal and state income tax purposes. Our returns for 2004 and subsequent tax '
                'years remain subject to examination in U.S. state and foreign jurisdictions.\n'
