    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 122)',
        'text': 'INTRODUCTION\n'
                '\n'
                'Tesla, Inc. (together with its subsidiaries, the “Company’) opposes the unauthorized disclosure of '
                'any nonpublic information acquired in the course of your service with the Company and the misuse of '
                'material nonpublic information in securities trading. Any such actions will be deemed violations of '
                'this Insider Trading Policy (the “Policy’) and you may be subject to disciplinary actions as '
                'described below.\n'
                '\n'
                'Legal prohibitions on insider trading\n'
                '\n'
                'The antifraud provisions of U.S. federal securities laws prohibit directors, officers, employees and '
                'other individuals who possess material nonpublic information from trading on the basis of that '
                'information. Transactions will be considered “on the basis of” material nonpublic information if the '
                'person engaged in the transaction was aware of the material nonpublic information at the time of the '
                'transaction. It is not a defense that the person did not “use” the information for purposes of the '
                'transaction.\n'
                '\n'
                'Disclosing material nonpublic information directly or indirectly to others who then trade based on '
                'that information or making recommendations or expressing opinions as to transactions in securities '
                'while aware of material nonpublic information (which is sometime referred to as “tipping’) is also '
                'illegal. Both the person who provides the information, recommendation or opinion and the person who '
                'trades based on it may be liable.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 122)',
        'text': 'These illegal activities are commonly referred to as “insider trading.” State securities laws and '
                'securities laws of other jurisdictions also impose restrictions on insider trading.\n'
                '\n'
                'In addition, a company, as well as individual directors, officers and other supervisory personnel, '
                'may be subject to liability as “controlling persons” for failure to take appropriate steps to prevent '
                'insider trading by those under their supervision, influence or control.\n'
                '\n'
                'It is also Company policy to comply with applicable securities laws concerning trading in Company '
                'securities on the Company’s behalf.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 122)',
        'text': 'Detection and prosecution of insider trading\n'
                '\n'
                'The U.S. Securities and Exchange Commission (the “SEC’), the Financial Industry Regulatory Authority '
                'and the Nasdaq Stock Market use sophisticated electronic surveillance techniques to investigate and '
                'detect insider trading, and the SEC and the U.S. Department of Justice pursue insider trading '
                'violations vigorously. Cases involving trading through foreign accounts, trading family members and '
                'friends and trading involving only a small number of shares have been successfully prosecuted.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 122)',
        'text': 'Penalties for violation of insider trading laws and this Policy\n'
                '\n'
                'Civil and criminal penalties. As of the effective date of this Policy, potential penalties for '
                'insider trading violations under U.S. federal securities laws include:\n'
                '\n'
                '. imprisonment;\n'
                '\n'
                '. disgorging any profits made or losses avoided;\n'
                '\n'
                '. substantial criminal fines;\n'
                '\n'
                '. substantial damages in a private lawsuit;\n'
                '\n'
                '. substantial civil fines based on the profit gained or loss avoided;\n'
                '\n'
                'a bar against serving as an officer or director of a public company; and\n'
                '\n'
                '.\n'
                '\n'
                '. an injunction against future violations.\n'
                '\n'
                'Page 1\n'
                '\n'
                'by\n'
                '\n'
                'Civil and criminal penalties also apply to tipping. The SEC has imposed large penalties in tipping '
                'cases even when the disclosing person did not trade or gain any benefit from another person’s '
                'trading.\n'
                '\n'
                'Controlling person liability. As of the effective date of this Policy, the penalty for “controlling '
                'person” liability includes civil fines, as well as potential criminal fines and imprisonment. The '
                'civil penalties can extend personal liability to directors, officers and managers.\n'
                '\n'
                'Company disciplinary actions. \\f the Company has a reasonable basis to conclude that you have failed '
                'to comply with this Policy, you may be subject to disciplinary action by the Company, up to and '
                'including dismissal for cause, regardless of whether or not your failure to comply with this Policy '
                'results in a violation of law. It is not necessary for the Company to wait for the filing or '
                'conclusion of any civil or criminal action against an alleged violator before taking disciplinary '
                'action. In addition, the Company may give stop transfer and other instructions to the Company’s '
                'transfer agent to enforce compliance with this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 123)',
        'text': 'Insider Trading Compliance Officer\n'
                '\n'
                'Please direct any questions, requests or reports as to any of the matters discussed in this Policy to '
                'the Company’s Insider Trading Compliance Officer, who is the Company’s General Counsel, or in the '
                'absence of a General Counsel, someone acting in the General Counsel’s stead (the “/nsider Trading '
                'Compliance Officer’). The Insider Trading Compliance Officer is generally responsible for the '
                'administration of this Policy. The Insider Trading Compliance Officer may select others to assist '
                'with the execution of such Officer’s duties, each of whom shall also be referred to as the Insider '
                'Trading Compliance Officer for purposes of this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 123)',
        'text': 'Reporting violations\n'
                '\n'
                'It is your responsibility to help enforce this Policy. You should be alert to possible violations and '
                'promptly report violations or suspected violations of this Policy to the Insider Trading Compliance '
                'Officer. If your situation requires that your identity be kept secret, your anonymity will be '
                'preserved to the greatest extent reasonably possible. If you wish to remain anonymous, you may send a '
                'letter addressed to the Insider Trading Compliance Officer at Tesla, Inc., 1 Tesla Road, Austin, '
                'Texas 78725 or through the Integrity Line pursuant to the reporting procedures set forth in the '
                'Company’s Code of Business Ethics. If you make an anonymous report, please provide as much detail as '
                'possible, including any evidence that you believe may be relevant to the possible violation.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 123)',
        'text': 'Personal responsibility\n'
                '\n'
                'The ultimate responsibility for complying with this Policy and applicable laws and regulations rests '
                'with you. If securities transactions ever become the subject of scrutiny, they are likely to be '
                'viewed after- the-fact with the benefit of hindsight. As a result, you should use your best judgment '
                'at all times and carefully consider how the transaction may be construed in the bright light of '
                'hindsight. We advise you to seek assistance if you have any questions at all and consult with your '
                'personal legal and financial advisors, as needed. The rules relating to insider trading can be '
                'complex, and a violation of insider trading laws can carry severe consequences.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 123)',
        'text': 'PERSONS AND TRANSACTIONS COVERED BY THIS POLICY\n'
                '\n'
                'Persons covered by this Policy\n'
                '\n'
                'This Policy applies to all directors, officers, employees and agents (such as consultants and '
                'independent contractors) of the Company. This Policy also applies to your family members who reside '
                'with you, anyone else who lives in your household, and family members who do not live in your '
                'household but whose securities transactions are directed by you or are subject to your influence or '
                'control (such as parents or\n'
                '\n'
                'Page 2\n'
                '\n'
                'children who consult with you before they trade in Company securities), as well as persons that are '
                'your economic dependents and any other individuals or entities whose transactions in securities you\n'
                '\n'
                'influence, direct or control (including, for example, a venture or other investment fund, if you '
                'influence, direct or control transactions by the fund) (such individuals and entities, “Additional '
                'Covered Persons”). You are responsible for making sure that these Additional Covered Persons comply '
                'with this Policy. Accordingly, you should make such Additional Covered Persons aware of the need to '
                'confer with you before they trade in Company Securities, and you should treat all such transaction '
                'for the purposes of this Policy and applicable securities laws concerning trading while in possession '
                'of material nonpublic information as if the transactions were from your own account.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 124)',
        'text': 'Types of transactions covered by this Policy\n'
                '\n'
                'Except as discussed in the section entitled “Limited Exceptions,” this Policy applies to a// '
                'transactions /nvo/ving the securities of the Company or the securities of other companies as to which '
                'you possess material nonpublic information obtained in the course of your service with the Company. '
                'This Policy therefore applies to purchases, sales and other transfers of common stock, options, '
                'warrants, preferred stock, debt securities (such as debentures, bonds and notes) and other '
                'securities. This Policy also applies to any arrangements that affect economic exposure to changes in '
                'the prices of these securities. These arrangements may include, among other things, transactions in '
                'derivative securities (such as exchange-traded put or call options), hedging transactions, short '
                'sales and certain decisions with respect to participation in benefit plans. This Policy also applies '
                'to any offers with respect to the transactions discussed above. You should note that there are no '
                'exceptions from insider trading laws or this Policy based on the size of the transaction.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 124)',
        'text': 'Responsibilities regarding the nonpublic information of other companies\n'
                '\n'
                'This Policy prohibits the unauthorized disclosure or other misuse of any nonpublic information of '
                'other companies, such as the Company’s distributors, vendors, customers, collaborators, suppliers and '
                'competitors. This Policy also prohibits insider trading and tipping based on the material nonpublic '
                'information of other companies.\n'
                '\n'
                'Applicability of this Policy after your departure\n'
                '\n'
                'You are expected to comply with this Policy until such time as you are no longer affiliated with the '
                'Company and you no longer possess any material nonpublic information subject to this Policy. In '
                'addition, if you are subject to a trading blackout under this Policy at the time you cease to be '
                'affiliated with the Company, you are expected to abide by the applicable trading restrictions until '
                'at least the end of the relevant blackout period.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 124)',
        'text': 'No exceptions based on personal circumstances\n'
                '\n'
                'There may be instances where you suffer financial harm or other hardship or are otherwise required to '
                'forgo a planned transaction because of the restrictions imposed by this Policy. Personal financial '
                'emergency or other personal circumstances are not mitigating factors under securities laws and will '
                'not excuse a failure to comply with this Policy.\n'
                '\n'
                'MATERIAL NONPUBLIC INFORMATION\n'
                '\n'
                '“Material” information\n'
                '\n'
                'Information should be regarded as material if there is a substantial likelihood that a reasonable '
                'investor would consider it important in deciding whether to buy, hold or sell securities or would '
                'view the information as significantly altering the total mix of information in the marketplace about '
                'the issuer of the\n'
                '\n'
                'Page 3\n'
                '\n'
                'security. In general, any information that could reasonably be expected to affect the market price of '
                'a security is likely to material. Either positive or negative information may be material.\n'
                '\n'
                'It is not possible to define all categories of “material” information. However, some examples of '
                'information that could be regarded as material include information with respect to:\n'
                '\n'
                '°\n'
                '\n'
                'Financial results, financial condition, earnings pre-announcements, guidance, projections or '
                'forecasts, particularly inconsistent with the Company’s guidance or the expectations of the '
                'investment community;\n'
                '\n'
                '°\n'
                '\n'
                'Restatements of financial results, or material impairments, write-offs or restructurings;\n'
                '\n'
                '°\n'
                '\n'
                'Changes in independent auditors, or notification that the Company may no longer rely on an audit '
                'report;\n'
                '\n'
                '° Business plans or budgets;\n'
                '\n'
                '° Creation of significant financial obligations, or any significant default under or acceleration of '
                'any financial obligation;\n'
                '\n'
                'Impending bankruptcy or financial liquidity problems;\n'
                '\n'
                '°\n'
                '\n'
                '°\n'
                '\n'
                'Significant developments involving business relationships, including execution, modification or '
                'termination of significant agreements or orders with customers, suppliers, distributors, '
                'manufacturers or other business partners;\n'
                '\n'
                '°\n'
                '\n'
                'Product introductions, modifications, defects or recalls or significant pricing changes or other '
                'product announcements of a significant nature;\n'
                '\n'
                '°\n'
                '\n'
                'Significant developments in research and development or relating to intellectual property;\n'
                '\n'
                '° Significant cybersecurity incidents;\n'
                '\n'
                '° Significant legal or regulatory developments, whether actual or threatened;\n'
                '\n'
                '°\n'
                '\n'
                'Actual or threatened major litigation or governmental proceedings or investigations, or the actual or '
                'potential settlement of such litigation, proceedings or investigations;\n'
                '\n'
                '°\n'
                '\n'
                'Major events involving the Company’s securities, including calls of securities for redemption, '
                'adoption of stock repurchase programs, option repricings, stock splits, changes in dividend policies, '
                'public or private securities offerings, modification to the rights of security holders or notice of '
                'delisting;'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 125)',
        'text': '°\n'
                '\n'
                'Significant corporate events, such as a pending or proposed merger, joint venture or tender offer, a '
                'significant investment, the acquisition or disposition of a significant business or asset or a change '
                'in control of the Company;\n'
                '\n'
                '° The existence of a special blackout period; and\n'
                '\n'
                'Major personnel changes, such as changes in senior management or lay-offs, or changes in the board of '
                'directors.\n'
                '\n'
                '°\n'
                '\n'
                'If you have any questions as to whether information should be considered “material,” you should '
                'consult with the Trading Compliance Officer. In general, it is advisable to resolve any close '
                'questions as to the materiality of any information assuming that the information is material.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 125)',
        'text': '“Nonpublic” information\n'
                '\n'
                'Information is considered nonpublic if the information has not been broadly disseminated to the '
                'public for a sufficient period be reflected in the price of the security. Information can be broadly '
                'disseminated to the public in a press release, a public with the SEC, a pre-announced public webcast '
                'or another broad,\n'
                '\n'
                'Page 4\n'
                '\n'
                'be\n'
                '\n'
                'if\n'
                '\n'
                'Insider by\n'
                '\n'
                'to filing\n'
                '\n'
                'non-exclusionary form of public communication. You may not attempt to “beat the market” by trading '
                'simultaneously with, or shortly after, the official release of material information. Although there '
                'is no fixed period for how long it takes the market to absorb information, out of prudence a person '
                'in possession of material nonpublic information should refrain from any trading activity for at least '
                'one full trading day following its official release. Any questions as to whether information is '
                'nonpublic should be directed to the Insider Trading Compliance Officer.\n'
                '\n'
                'The term “trading day’ means a day on which national stock exchanges are open for trading. A “fulf’ '
                'trading day has elapsed when, after the public disclosure, trading in the relevant security has '
                'opened and then closed.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 126)',
        'text': 'POLICIES REGARDING MATERIAL NONPUBLIC INFORMATION\n'
                '\n'
                'Confidentiality of nonpublic information\n'
                '\n'
                'The unauthorized use or disclosure of nonpublic information relating to the Company or other '
                'companies is prohibited. All nonpublic information you acquire in the course of your service with the '
                'Company may only be used for legitimate Company business purposes. In addition, nonpublic information '
                'of others should be handled in accordance with the terms of any relevant nondisclosure agreements, '
                'and the use of any such nonpublic information should be limited to the purpose for which it was '
                'disclosed.\n'
                '\n'
                'You must use all reasonable efforts to safeguard nonpublic information in the Company’s possession. '
                'You may not disclose nonpublic information about the Company or any other company, unless required by '
                'law, or unless (i) disclosure is required for legitimate Company business purposes, (ii) you are '
                'authorized to disclose the information and (iii) appropriate steps have been taken to prevent misuse '
                'of that information (for example, entering into an appropriate nondisclosure agreement that restricts '
                'the disclosure and use of the information, if applicable). This restriction also applies to internal '
                'communications within the Company and to communications with agents of the Company. In cases where '
                'disclosing nonpublic information to third parties is required, you should coordinate with the Legal '
                'Department.\n'
                '\n'
                'In addition, all officers, employees and agents of the Company are required to comply with any '
                'confidential information or invention assignment agreement with the Company to which they are '
                'subject.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 126)',
        'text': 'No trading on material nonpublic information\n'
                '\n'
                'Except as discussed in the section entitled “Limited Exceptions” below, you may not, directly or '
                'indirectly through others, engage in any transaction involving the Company’s securities while aware '
                'of material nonpublic information relating to the Company. It is not an excuse that you did not “use” '
                'the information in your transaction.\n'
                '\n'
                'Similarly, you may not engage in transactions involving the securities of any other company if you '
                'are aware of material nonpublic information about that company (except to the extent the transactions '
                'are analogous to those presented in the section entitled “Limited Exceptions”). For example, you may '
                'be involved in a proposed transaction involving a prospective business relationship or transaction '
                'with another company. If information about that transaction constitutes material nonpublic '
                'information for that other company, you would be prohibited from engaging in transactions involving '
                'the securities of that other company (as well as transactions involving Company securities, if that '
                'information is material to the Company). It is important to note that “materiality” is different for '
                'different companies. Information that is not material to the Company may be material to another '
                'company.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 126)',
        'text': 'No disclosing material nonpublic information for the benefit of others\n'
                '\n'
                'Page 5\n'
                '\n'
                'You may not disclose material nonpublic information concerning the Company or any other company to '
                'friends, family members or any other person or entity not authorized to receive such information '
                'where such person or entity may benefit by trading on the basis of such information. In addition, you '
                'may not make recommendations or express opinions on the basis of material nonpublic information as to '
                'trading in the securities of companies to which such information relates. You are prohibited from '
                'engaging in these actions whether or not you derive any profit or personal benefit from doing so. '
                'This prohibition against\n'
                '\n'
                'disclosure of material nonpublic information includes disclosure (even anonymous disclosure) via the '
                'internet, blogs, investor forums or chat rooms where companies and their prospects are discussed.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 127)',
        'text': 'Responding to outside inquiries for information\n'
                '\n'
                'In the event you receive an inquiry from someone outside of the Company, such as a stock analyst, for '
                'information, you should refer the inquiry to the Company’s Investor Relations Department. The Company '
                'is required under Regulation FD (Fair Disclosure) of the U.S. federal securities laws to avoid the '
                'selective disclosure of material nonpublic information. In general, the regulation provides that when '
                'a public company discloses material nonpublic information, it must provide broad, non-exclusionary '
                'access to the information. Violations of this regulation can subject the Company to SEC enforcement '
                'actions, which may result in injunctions and severe monetary penalties. The Company has established '
                'procedures for releasing material information in a manner that is designed to achieve broad public '
                'dissemination of the information immediately upon its release in compliance with applicable law. '
                'Please consult the Company’s External Communications Policy for more details.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 127)',
        'text': 'TRADING BLACKOUT PERIODS\n'
                '\n'
                'To limit the likelihood of trading at times when there is a significant risk of insider trading '
                'exposure, the Company has instituted quarterly trading blackout periods and may institute special '
                'trading blackout periods from time to time. In addition, to comply with applicable legal '
                'requirements, the Company may also institute blackout periods that prevent directors and officers '
                'from trading in Company securities at a time when employees are prevented from trading Company '
                'securities in the Company’s 401(k) plan\n'
                '\n'
                'It is important to note that whether or not you are subject to a particular blackout period, you '
                'remain subject to the prohibitions on trading on the basis of material nonpublic information and any '
                'other applicable restrictions in this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 127)',
        'text': 'Quarterly blackout periods\n'
                '\n'
                'Except as discussed in the section entitled “Limited Exceptions” below, all directors and executive '
                'officers, and employees and agents identified by the Company must refrain from conducting '
                'transactions involving the Company’s securities during quarterly blackout periods. Even if you are '
                'not specifically identified as being subject to quarterly blackout periods, you should exercise '
                'caution when engaging in transactions during quarterly blackout periods because of the heightened '
                'risk of insider trading exposure.\n'
                '\n'
                'Quarterly blackout periods begin at the end of the first trading day following the fifteenth day of '
                'the last month of each fiscal quarter and end after the first full trading day following public '
                'disclosure of the financial results for that fiscal quarter. This period is a particularly sensitive '
                'time for transactions involving the Company’s securities from the perspective of compliance with '
                'applicable securities laws due to the fact that, during this period, individuals may often possess or '
                'have access to material nonpublic information relevant to the expected financial results for the '
                'quarter. However, irrespective of whether you actually possess, have access to, or access such '
                'information, any failure to comply with a quarterly blackout period other than in accordance with the '
                'section entitled “Limited Exceptions” below will be a violation of this Policy.\n'
                '\n'
                'Page 6\n'
                '\n'
                'From time to time, the Company may identify persons who should be subject to quarterly blackout '
                'periods, and shall notify such persons. Additional Covered Persons associated with such individuals '
                'so notified are also subject to the quarterly blackout periods.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 128)',
        'text': 'Special blackout periods\n'
                '\n'
                'From time to time, the Company may also prohibit directors, officers, employees and agents from '
                'engaging in transactions involving the Company’s securities when, in the judgment of the Insider '
                'Trading Compliance Officer, a trading blackout is warranted. The Company will generally impose '
                'special blackout periods when there are material developments known to the Company that have not yet '
                'been disclosed to the public. For example, the Company may impose a special blackout period in '
                'anticipation of announcing interim earnings guidance or a significant transaction or business '
                'development. However, special blackout periods may be declared for any reason.\n'
                '\n'
                'The Company will notify those persons subject to a special blackout period. Each person who has been '
                'so identified and notified by the Company (and related Additional Covered Persons) may not engage in '
                'any transaction involving the Company’s securities until instructed otherwise by the Insider Trading '
                'Compliance Officer.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 128)',
        'text': 'Regulation BTR blackouts\n'
                '\n'
                'Directors and executive officers may also be subject to trading blackouts pursuant to Regulation '
                'Blackout Trading Restriction, or Regulation BTR, under U.S. federal securities laws. In general, '
                'Regulation BTR prohibits any director or executive officer from engaging in certain transactions '
                'involving Company securities during periods when 401(k) plan participants are prevented from '
                'purchasing, selling or otherwise acquiring or transferring an interest in certain securities held in '
                'individual account plans. Any profits realized from a transaction that violates Regulation BTR are '
                'recoverable by the Company, regardless of the intentions of the director or officer effecting the '
                'transaction. In addition, individuals who engage in such transactions are subject to sanction by the '
                'SEC as well as potential criminal liability. The Company has provided, or will provide, separate '
                'memoranda and other appropriate materials to its directors and executive officers regarding '
                'compliance with Regulation BTR.\n'
                '\n'
                'The Company will notify directors and officers if they are subject to a blackout trading restriction '
                'under Regulation BTR. Failure to comply with an applicable trading blackout in accordance with '
                'Regulation BTR is a violation of law and this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 128)',
        'text': 'No “safe harbors”\n'
                '\n'
                'There are no unconditional “safe harbors” for trades made at particular times, and all persons '
                'subject to this Policy should exercise good judgment at all times. Even when a quarterly blackout '
                'period is not in effect, you may be prohibited from engaging in transactions involving the Company’s '
                'securities because you possess material nonpublic information, are subject to a special blackout '
                'period or are otherwise restricted under this Policy.\n'
                '\n'
                'PRE-CLEARANCE OF TRADES\n'
                '\n'
                'Except as discussed in the section entitled “Limited Exceptions” below, directors and executive '
                'officers should refrain from engaging in any transaction involving the Company’s securities without '
                'first obtaining pre-clearance of the transaction from the Insider Trading Compliance Officer. In '
                'addition, the Company has determined that certain other employees and agents of the Company that may '
                'have regular or special access to material nonpublic information should refrain from engaging in any '
                'transaction involving the Company’s securities without first obtaining pre-clearance of the '
                'transaction from the Insider Trading Compliance Officer. The Insider Trading Compliance Officer may '
                'not engage in a transaction involving the\n'
                '\n'
                'Page 7\n'
                '\n'
                'Company’s securities unless the Company’s Chief Executive Officer, Chief Financial Officer, Chief '
                'Accounting Officer or their delegate, or if there are more than one Insider Trading Compliance '
                'Officer, another such Insider Trading Compliance Officer, has pre-cleared the transaction. '
                'Individuals\n'
                '\n'
                'subject to pre-clearance requirements are listed on Schedule A. From time to time, the Company may '
                'identify other persons who should be subject to the pre-clearance requirements set forth above, and '
                'the Insider Trading Compliance Officer may update and revise Schedule A as appropriate.\n'
                '\n'
                'These pre-clearance procedures are intended to decrease insider trading risks associated with '
                'transactions by individuals with regular or special access to material nonpublic information. In '
                'addition, requiring pre-clearance of transactions by directors and officers facilitates compliance '
                'with Rule 144 resale restrictions under the Securities Act of 1933, as amended and the liability and '
                'reporting provisions of Section 16 under the Securities Exchange Act of 1934, as amended (the '
                '“Exchange Act’) and Regulation BTR. Pre-clearance of a trade, however, is not a defense to a claim of '
                'insider trading and does not excuse you from otherwise complying with insider trading laws or this '
                'Policy. Further, pre-clearance of a transaction does not constitute an affirmation by the Company or '
                'the Insider Trading Compliance Officer that you are not in possession of material nonpublic '
                'information.\n'
                '\n'
                'The Insider Trading Compliance Officer is under no obligation to approve a transaction submitted for '
                'pre-clearance, and may determine not to permit the transaction.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 129)',
        'text': 'ADDITIONAL RESTRICTIONS AND GUIDANCE\n'
                '\n'
                'This section addresses certain types of transactions that may expose you and the Company to '
                'significant risks. You should understand that, even though a transaction may not be expressly '
                'prohibited by this section, you are responsible for ensuring that the transaction otherwise complies '
                'with other provisions in this Policy that may apply to the transaction, such as the general '
                'prohibition against insider trading as well as pre- clearance procedures and blackout periods, to the '
                'extent applicable.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 129)',
        'text': 'Short sales\n'
                '\n'
                'Short sales (/.e., the sale of a security that must be borrowed to make delivery) and “selling short '
                'against the box” (/.e., a sale with a delayed delivery) with respect to Company securities are '
                'prohibited under this Policy. Short sales may signal to the market possible bad news about the '
                'Company or a general lack of confidence in the Company’s prospects, and an expectation that the value '
                'of the Company’s securities will decline. In addition, short sales are effectively a bet against the '
                'Company’s success and may reduce the seller’s incentive to improve the Company’s performance. Short '
                'sales may also create a suspicion that the seller is engaged in insider trading.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 129)',
        'text': 'Derivative securities and hedging transactions\n'
                '\n'
                'You are prohibited from engaging in transactions in publicly-traded options, such as puts and calls, '
                'and other derivative securities with respect to the Company’s securities. This prohibition extends to '
                'any hedging or similar transaction designed to decrease the risks associated with holding Company '
                'securities. Stock options, stock appreciation rights, other securities issued pursuant to Company '
                'benefit plans or other compensatory arrangements with the Company, and broad-based index options, '
                'futures or baskets are not subject to this prohibition.\n'
                '\n'
                'Transactions in derivative securities may reflect a short-term and speculative interest in the '
                'Company’s securities and may create the appearance of impropriety, even where a transaction does not '
                'involve trading on inside information. Trading in derivatives may also focus attention on short-term '
                'performance at the expense of the Company’s long-term objectives. In addition, the application of '
                'securities laws to derivatives\n'
                '\n'
                'Page 8\n'
                '\n'
                'transactions can be complex, and persons engaging in derivatives transactions run an increased risk '
                'of violating securities laws.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 130)',
        'text': 'Using Company securities as collateral for loans\n'
                '\n'
                'You should exercise caution in pledging Company securities as collateral for loans. If you default on '
                'the loan, the lender may sell the pledged securities as collateral in a foreclosure sale. The sale, '
                'even though not initiated at your request, is still considered a sale for your benefit and, if made '
                'at a time when you are aware of material nonpublic information or otherwise are not permitted to '
                'trade in Company securities, may result in inadvertent insider trading violations, Section 16 and '
                'Regulation BTR violations (for officers and directors), violations of this Policy and unfavorable '
                'publicity for you and the Company.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 130)',
        'text': 'Holding Company securities in margin accounts\n'
                '\n'
                'You may not hold Company securities in margin accounts. Under typical margin arrangements, if you '
                'fail to meet a margin call, the broker may be entitled to sell securities held in the margin account '
                'without your consent. The sale, even though not initiated at your request, is still considered a sale '
                'for your benefit and, if made at a time when you are aware of material nonpublic information or are '
                'otherwise not permitted to trade, may result in inadvertent insider trading violations, Section 16 '
                'violations (for officers and directors), violations of this Policy and unfavorable publicity for you '
                'and the Company.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 130)',
        'text': 'Placing open orders with brokers\n'
                '\n'
                'Except in accordance with an approved trading plan (as discussed below), you should exercise caution '
                'when placing open orders, such as limit orders or stop orders, with brokers, particularly where the '
                'order is likely to remain outstanding for an extended period of time. Open orders may result in the '
                'execution of a trade at a time when you are aware of material nonpublic information or otherwise are '
                'not permitted to trade in Company securities, which may result in inadvertent insider trading '
                'violations, Section 16 and Regulation BTR violations (for officers and directors), violations of this '
                'Policy and unfavorable publicity for you and the Company. If you are subject to any blackout periods '
                'or pre-clearance requirements, you should inform any broker with whom you place any open order at the '
                'time it is placed of your obligation to comply with such blackout periods and/or pre- clearance '
                'requirements.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 130)',
        'text': 'LIMITED EXCEPTIONS\n'
                '\n'
                'The following are certain limited exceptions to the restrictions imposed by the Company under this '
                'Policy. Please be aware that even if a transaction is subject to an exception to this Policy, you '
                'will need to separately assess whether the transaction complies with applicable law. For example, '
                'even if a transaction is indicated as exempt from this Policy, you may need to comply with the '
                '“short-swing” trading restrictions under Section 16 of the Exchange Act, to the extent applicable. '
                'You are responsible for complying with applicable law at all times.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 130)',
        'text': 'Transactions pursuant to a trading plan that complies with SEC rules\n'
                '\n'
                'The SEC has enacted rules that provide an affirmative defense against alleged violations of U.S. '
                'federal insider trading laws for transactions pursuant to trading plans that meet certain '
                'requirements. In general, these rules, as set forth in Rule 10b5-1 under the Exchange Act, provide '
                'for an affirmative defense if you enter into a contract, provide instructions or adopt a written plan '
                'for trading securities when you are not aware of material nonpublic information. The contract, '
                'instructions or plan must be made or entered into in good faith and not as a part of a plan or scheme '
                'to evade the insider trading laws and must (i) specify the amount, price and date of the transaction, '
                '(ii) specify an objective method for determining the amount, price and date of the transaction and/or '
                '(iii) place any subsequent discretion for determining the amount, price and\n'
                '\n'
                'Page 9\n'
                '\n'
                'date of the transaction in another person who is not, at the time of the transaction, aware of '
                'material nonpublic information.\n'
                '\n'
                'Transactions made pursuant to a written trading plan that (i) complies with the affirmative defense '
                'set forth in Rule 10b5-1 and (ii) is approved by the Insider Trading Compliance Officer, are not '
                'subject to the restrictions in this Policy against trades made while aware of material nonpublic '
                'information or to the pre- clearance procedures or blackout periods established under this Policy. In '
                'approving a trading plan, the Insider Trading Compliance Officer may, in furtherance of the '
                'objectives expressed in this Policy, impose criteria in addition to those set forth in Rule 10b5-1. '
                'Therefore, you must confer with the Insider Trading Compliance Officer prior to entering into any '
                'trading plan. No transactions may occur under such contract, instructions or plans until the '
                'expiration of the applicable cooling-off period (minimum of 90 days for directors and officers and 30 '
                'days for all other employees and agents).\n'
                '\n'
                'The SEC rules regarding trading plans are complex and must be complied with completely to be '
                'effective. The description provided above is only a summary, and the Company strongly advises that '
                'you consult with your personal legal advisor if you intend to adopt a trading plan. While trading '
                'plans are subject to review and approval by the Company, the individual adopting the trading plan is '
                'ultimately responsible for compliance with Rule 10b5-1 and ensuring that the trading plan complies '
                'with this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 131)',
        'text': 'Trading plans must be filed with the Insider Trading Compliance Officer. The Company may publicly '
                'disclose information regarding trading plans that you may enter into.\n'
                '\n'
                'Receipt and vesting of stock options, restricted stock units, restricted stock and stock appreciation '
                'rights\n'
                '\n'
                'The trading restrictions under this Policy do not apply to the grant or award to you of stock '
                'options, restricted stock units, restricted stock or stock appreciation rights by the Company. The '
                'trading restrictions under this Policy also do not apply to the vesting, cancellation or forfeiture '
                'of stock options, restricted stock units, restricted stock or stock appreciation rights in accordance '
                'with applicable plans and agreements. However, the trading restrictions do apply to any subsequent '
                'sales of any such securities.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 131)',
        'text': 'Exercise of stock options for cash\n'
                '\n'
                'The trading restrictions under this Policy do not apply to the exercise of stock options for cash '
                'under the Company’s stock option plans. Likewise, the trading restrictions under this Policy do not '
                'apply to the exercise of stock options in a stock-for-stock exercise with the Company or an election '
                'to have the Company withhold securities to cover tax obligations in connection with an option '
                'exercise. However, the trading restrictions under this Policy do apply to (i) the sale of any '
                'securities issued upon the exercise of a stock option, (ii) a cashless exercise of a stock option '
                'through a broker, since this involves selling a portion of the underlying shares to cover the costs '
                'of exercise, and (iii) any other market sale for the purpose of generating the cash needed to pay the '
                'exercise price of an option.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 131)',
        'text': 'Purchases from the employee stock purchase plan\n'
                '\n'
                'The trading restrictions in this Policy do not apply to elections with respect to participation in '
                'the Company’s employee stock purchase plan or to purchases of securities under the plan. However, the '
                'trading restrictions do apply to any subsequent sales of any such securities.\n'
                '\n'
                'Certain 401(k) plan transactions\n'
                '\n'
                'The trading restrictions in this Policy do not apply to purchases of Company stock in the 401(k) plan '
                'resulting from periodic contributions to the plan based on your payroll contribution election. The '
                'trading restrictions do apply, however, to elections you make under the 401(k) plan to (i) increase '
                'or decrease the\n'
                '\n'
                'Page 10\n'
                '\n'
                'percentage of your contributions that will be allocated to a Company stock fund, (ii) move balances '
                'into or out of a Company stock fund, (iii) borrow money against your 401(k) plan account if the loan '
                'will result in liquidation of some or all of your Company stock fund balance, and (iv) pre-pay a plan '
                'loan if the pre- payment will result in the allocation of loan proceeds to a Company stock fund.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 132)',
        'text': 'Stock splits, stock dividends and similar transactions\n'
                '\n'
                'The trading restrictions under this Policy do not apply to a change in the number of securities held '
                'as a result of a stock split stock dividend applying equally to all securities of a class, or similar '
                'transactions.\n'
                '\n'
                'Inheritance and bona fide gifts\n'
                '\n'
                'The trading restrictions under this Policy do not apply to transfers by will or the laws of descent '
                'and distribution. In addition, bona fide gifts involving Company securities are not transactions '
                'subject to this policy, unless you have reason to believe that the recipient intends to sell the '
                'Company securities while you are aware of material nonpublic information.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 132)',
        'text': 'Change in form of ownership\n'
                '\n'
                'Transactions that involve merely a change in the form in which you own securities are not subject to '
                'the trading restrictions under this Policy. For example, you may transfer shares to an /nter vivos '
                'trust of which you are the sole beneficiary during your lifetime.\n'
                '\n'
                'Other exceptions\n'
                '\n'
                'Any other exception from this Policy must be approved by the Insider Trading Compliance Officer, in '
                'consultation with Board of Directors or an independent committee of the Board of Directors.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 132)',
        'text': 'COMPLIANCE WITH SECTION 16 OF THE SECURITIES EXCHANGE ACT\n'
                '\n'
                'Obligations under Section 16\n'
                '\n'
                'Section 16 of the Exchange Act, and the related rules and regulations, set forth (i) reporting '
                'obligations, (ii) limitations on “short-swing” transactions and (iii) limitations on short sales and '
                'other transactions applicable to directors, officers, large shareholders and certain other persons.\n'
                '\n'
                'The Board of Directors of the Company has determined that the persons specified as Section 16 '
                'insiders on Schedule A are required to comply with Section 16 of the Exchange Act, and the related '
                'rules and regulations, because of their positions with the Company. The Insider Trading Compliance '
                'Officer may amend Schedule A from time to time as appropriate to reflect the election of new officers '
                'or directors, any change in the responsibilities of officers or other employees and any promotions, '
                'demotions, resignations or departures.\n'
                '\n'
                'Schedule A may not necessarily contain an exhaustive list of persons subject to Section 16 '
                'requirements at any given time. Even if you are not listed on Schedule A, you may be subject to '
                'Section 16 reporting obligations because of your shareholdings, for example.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 132)',
        'text': 'Notification requirements to facilitate Section 16 reporting\n'
                '\n'
                'To facilitate timely reporting of transactions pursuant to Section 16 requirements, each person '
                'subject to Section 16 reporting requirements must provide, or must ensure that such person’s broker '
                'provides, the Company with detailed information (e.g., trade date, number of shares, exact price, '
                'etc.) regarding such person’s transactions involving the Company’s securities, including gifts, '
                'transfers, pledges and\n'
                '\n'
                'Page 11\n'
                '\n'
                'or\n'
                '\n'
                'the\n'
                '\n'
                'transactions pursuant to a trading plan, both prior to (to confirm compliance with pre-clearance '
                'procedures, if applicable) and promptly following execution.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 133)',
        'text': 'Personal responsibility\n'
                '\n'
                'The obligation to file Section 16 reports, and to otherwise comply with Section 16, is personal. The '
                'Company is not responsible for the failure to comply with Section 16 requirements.\n'
                '\n'
                'ADDITIONAL INFORMATION\n'
                '\n'
                'Availability of Policy\n'
                '\n'
                'This Policy will be made available to all directors, officers, employees and agents of the Company '
                'when they commence service with the Company. Each director, officer, employee and agent of the '
                'Company is required, if requested, to acknowledge that he or she understands, and agrees to comply '
                'with, this Policy.'},
    {   'source': 'NASDAQ_TSLA_2024.pdf (Page 133)',
        'text': 'Amendments\n'
                '\n'
                'We are committed to continuously reviewing and updating our policies and procedures. The Company '
                'therefore reserves the right to amend, alter or terminate this Policy at any time and for any reason, '
                "subject to applicable law. A current copy of the Company's policies regarding insider trading may be "
                'obtained by contacting the Insider Trading Compliance Officer.\n'
                '\n'
                'Ancillary Documents\n'
                '\n'
                'Attached as Schedule B are forms of various ancillary documents that may be used from time to time in '
                'connection with the matters discussed in this Policy. The Insider Trading Compliance Officer may '
                'amend, alter, substitute or terminate any of these ancillary documents at any time and for any '
                'reason, subject to applicable law.\n'
                '\n'
                '* * *\n'
                '\n'
                'Nothing in this Insider Trading Policy creates or implies an employment contract or term of '
                'employment.\n'
                '\n'
                'The policies in this Insider Trading Policy do not constitute a complete list of Company policies or '
                'a complete list of the types of conduct that can result in discipline, up to and including '
                'discharge.'},
